# ==============================================================================# 041_COMMAND_BUS.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")# ------------------------------------------------------------------------------# COMMAND TABLE# ------------------------------------------------------------------------------cur.execute("""CREATE TABLE IF NOT EXISTS command_bus(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    command_name TEXT,    target_service TEXT,    payload TEXT,    priority TEXT,    status TEXT,    executed_at TEXT)""")conn.commit()# ------------------------------------------------------------------------------# DEFAULT COMMANDS# ------------------------------------------------------------------------------COMMANDS = [("SYSTEM_STARTUP","MAESTRO","{}","CRITICAL"),("CHECK_HEALTH","HEALTH CHECK","{}","HIGH"),("COLLECT_METRICS","METRICS","{}","NORMAL"),("LOAD_PLUGINS","PLUGIN","{}","HIGH"),("SYNC_SERVICES","SERVICE MANAGER","{}","HIGH"),("CHECK_RUNTIME","RUNTIME","{}","NORMAL"),("VERIFY_SECURITY","SECURITY","{}","HIGH"),("GENERATE_DASHBOARD","DASHBOARD","{}","LOW")]for command,target,payload,priority in COMMANDS:    cur.execute("""    SELECT id    FROM command_bus    WHERE command_name=?    AND status='PENDING'    """,(command,))    if cur.fetchone() is None:        cur.execute("""        INSERT INTO command_bus(            created_at,            command_name,            target_service,            payload,            priority,            status,            executed_at        )        VALUES(?,?,?,?,?,?,?)        """,(            datetime.now().isoformat(),            command,            target,            payload,            priority,            "PENDING",            None        ))conn.commit()# ------------------------------------------------------------------------------# SHOW COMMANDS# ------------------------------------------------------------------------------cur.execute("""SELECTid,command_name,target_service,priority,statusFROM command_busORDER BYCASE priorityWHEN 'CRITICAL' THEN 1WHEN 'HIGH' THEN 2WHEN 'NORMAL' THEN 3WHEN 'LOW' THEN 4END,id""")rows = cur.fetchall()print("="*80)print("COMMAND BUS")print("="*80)for row in rows:    print(        f"{row['id']:03d} "        f"{row['priority']:<9}"        f"{row['command_name']:<24}"        f"{row['target_service']:<20}"        f"{row['status']}"    )print("="*80)print("TOTAL COMMANDS:",len(rows))print("="*80)conn.close()

